            let a0 = node(&args[0])?;
            let a1 = node(&args[1])?;
            let a2 = node(&args[2])?;
            let a3 = node(&args[3])?;
            let a4 = uint_arg(&args[4])?;
            let a5 = scope_arg(&args[5])?;
